user_stories:
{
  "user_stories": [
    {
      "id": 1,
      "role": "Dreamer",
      "goal": "Submit my dream's manifest content with consent and privacy settings",
      "benefit": "So my session can be safely saved and used for later interpretation",
      "acceptance_criteria": [
        "I can enter dream text, set privacy/retention preferences, and confirm consent before continuing",
        "The system creates a session and stores the manifest content with a timestamp"
      ]
    },
    {
      "id": 2,
      "role": "Freudian AI Analyst",
      "goal": "Generate 5–7 open-ended follow-up questions from the manifest content",
      "benefit": "So the Dreamer can free-associate and clarify affect, symbols, and conflicts",
      "acceptance_criteria": [
        "Exactly 5–7 questions are produced, each open-ended and framed in a professional, nonjudgmental tone",
        "Questions reference Freudian concepts when relevant (e.g., condensation, displacement, wish fulfillment) without definitive claims"
      ]
    },
    {
      "id": 3,
      "role": "Dreamer",
      "goal": "Answer the follow-up questions and edit my responses before analysis",
      "benefit": "So my associations are accurate and ready for latent-content exploration",
      "acceptance_criteria": [
        "I can answer each question, revise answers, and save them to the current session",
        "The system confirms all answers are stored and allows me to proceed to analysis"
      ]
    },
    {
      "id": 4,
      "role": "Freudian AI Analyst",
      "goal": "Produce a structured Freudian analysis using the dream and answers",
      "benefit": "So the Dreamer receives an exploratory interpretation, psychological reflection, and suggestions",
      "acceptance_criteria": [
        "The analysis includes sections covering manifest summary, latent hypotheses, wish-fulfillment themes, and mechanisms (e.g., condensation/displacement)",
        "It includes gentle well-being suggestions plus clear disclaimers (not diagnosis/therapy) and saves the full analysis to the session"
      ]
    },
    {
      "id": 5,
      "role": "Dreamer",
      "goal": "Review past dream sessions and their interpretations",
      "benefit": "So I can notice recurring themes and track changes over time",
      "acceptance_criteria": [
        "I can view a list of my sessions with dates and open any session to see dream, questions, answers, and analysis",
        "I can search or filter sessions and control deletion per my retention preferences"
      ]
    },
    {
      "id": 6,
      "role": "Administrator",
      "goal": "Manage and audit stored sessions with least-privilege access",
      "benefit": "So privacy, retention, and policy compliance are enforced",
      "acceptance_criteria": [
        "I can fulfill export/deletion requests and configure retention defaults without exposing more content than necessary",
        "All admin access to session data is logged for auditing and policy review"
      ]
    }
  ]
}
